example.code:
using Fuxion.Analyzers;

[HasMembersRequiringNotNull("Pod", "Json")]
public class FuxionExtensions<T> where T : notnull
{
    public T Value { get; }
}

extension<T>(FuxionExtensions<T?> me) where T : notnull
{
    // This property requires non-null, indicated by the class attribute
    public PodExtensions<T> Pod
    {
        get
        {
            ArgumentNullException.ThrowIfNull(me.Value);
            return new PodExtensions<T>(me.Value);
        }
    }
}

// Usage:
string? nullable = GetString();
nullable?.Fx.Pod.BuildUriKeyPod(resolver); // ? Correct
nullable.Fx.Pod.BuildUriKeyPod(resolver);  // ? Error FX001

member.remarks:
            This attribute is used by Roslyn analyzers to provide compile-time diagnostics
            when accessing members that enforce non-null constraints at runtime.



            When a property or method is marked with this attribute, the analyzer will:


Report an error when accessed on a nullable type without null-conditional operator

Suggest using the null-conditional operator (?) to safely handle null values





            using Fuxion.Analyzers;

            extension<T>(FuxionExtensions<T?> me) where T : notnull
            {
                [RequiresNotNull]
                public PodExtensions<T> Pod
                {
                    get
                    {
                        ArgumentNullException.ThrowIfNull(me.Value);
                        return new(me.Value);
                    }
                }
            }

            // Usage:
            string? nullable = GetNullableString();
            nullable?.Fx.Pod.BuildUriKeyPod(resolver); // ? Correct: uses null-conditional
            nullable.Fx.Pod.BuildUriKeyPod(resolver);  // ? Error: FX001
